// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;

import org.junit.jupiter.api.Test;

class LongVerdictMemoTest {

	private static final int[] ONE = { 0 };
	private static final int[] THREE = { 0, 2, 3 };

	@Test
	void anAbsentTupleReportsAbsent() {
		LongVerdictMemo memo = new LongVerdictMemo(1);
		assertEquals(LongVerdictMemo.ABSENT, memo.get(new long[] { 0 }, ONE));
		assertEquals(LongVerdictMemo.ABSENT, memo.get(new long[] { Long.MIN_VALUE }, ONE));
	}

	@Test
	void arityMustBePositive() {
		assertThrows(IllegalArgumentException.class, () -> new LongVerdictMemo(0));
	}

	@Test
	void everySentinelCandidateIsAStorableValue() {
		// occupancy lives in a side array, so no long value is reserved
		long[] awkward = { 0L, -1L, 1L, Long.MIN_VALUE, Long.MAX_VALUE };
		LongVerdictMemo memo = new LongVerdictMemo(1);
		for (int i = 0; i < awkward.length; i++) {
			memo.put(new long[] { awkward[i] }, ONE, i % 2 == 0);
		}
		assertEquals(awkward.length, memo.size());
		for (int i = 0; i < awkward.length; i++) {
			assertEquals(i % 2 == 0 ? 1 : 0, memo.get(new long[] { awkward[i] }, ONE), "value " + awkward[i]);
		}
	}

	@Test
	void aRepeatedPutOverwritesTheVerdictWithoutGrowing() {
		LongVerdictMemo memo = new LongVerdictMemo(1);
		long[] row = { 42L };
		memo.put(row, ONE, true);
		memo.put(row, ONE, false);
		memo.put(row, ONE, true);
		assertEquals(1, memo.size());
		assertEquals(1, memo.get(row, ONE));
	}

	@Test
	void onlyTheSelectedSlotsFormTheKey() {
		LongVerdictMemo memo = new LongVerdictMemo(3);
		memo.put(new long[] { 1, 999, 2, 3 }, THREE, true);
		// slot 1 is not part of the key, so a different value there must still hit
		assertEquals(1, memo.get(new long[] { 1, -7, 2, 3 }, THREE));
		// a change in a keyed slot must miss
		assertEquals(LongVerdictMemo.ABSENT, memo.get(new long[] { 1, 999, 2, 4 }, THREE));
		assertEquals(1, memo.size());
	}

	@Test
	void multiSlotVerdictsSurviveTheRehashesForcedByGrowth() {
		LongVerdictMemo memo = new LongVerdictMemo(3, 16);
		Map<List<Long>, Boolean> reference = new HashMap<>();
		Random random = new Random(0x5eed);
		for (int i = 0; i < 20_000; i++) {
			long[] row = { random.nextInt(400), 0, random.nextInt(400), random.nextInt(400) };
			boolean verdict = random.nextBoolean();
			memo.put(row, THREE, verdict);
			reference.put(List.of(row[0], row[2], row[3]), verdict);
		}
		assertEquals(reference.size(), memo.size());
		for (Map.Entry<List<Long>, Boolean> entry : reference.entrySet()) {
			List<Long> key = entry.getKey();
			long[] row = { key.get(0), 0, key.get(1), key.get(2) };
			assertEquals(entry.getValue() ? 1 : 0, memo.get(row, THREE), "key " + key);
		}
	}

	@Test
	void collidingKeysStayDistinctUnderLinearProbing() {
		LongVerdictMemo memo = new LongVerdictMemo(1, 16);
		for (int i = 0; i < 512; i++) {
			memo.put(new long[] { (long) i << 20 }, ONE, i % 3 == 0);
		}
		assertEquals(512, memo.size());
		for (int i = 0; i < 512; i++) {
			assertEquals(i % 3 == 0 ? 1 : 0, memo.get(new long[] { (long) i << 20 }, ONE), "key " + i);
		}
		assertEquals(LongVerdictMemo.ABSENT, memo.get(new long[] { 512L << 20 }, ONE));
	}

	@Test
	void memoAgreesWithAHashMapOverAMixedWorkload() {
		LongVerdictMemo memo = new LongVerdictMemo(2);
		int[] slots = { 0, 1 };
		Map<List<Long>, Boolean> reference = new HashMap<>();
		Random random = new Random(99);
		for (int i = 0; i < 50_000; i++) {
			long[] row = { random.nextInt(300), random.nextInt(300) };
			if (random.nextInt(4) == 0) {
				boolean verdict = random.nextBoolean();
				memo.put(row, slots, verdict);
				reference.put(List.of(row[0], row[1]), verdict);
			} else {
				Boolean expected = reference.get(List.of(row[0], row[1]));
				int actual = memo.get(row, slots);
				if (expected == null) {
					assertEquals(LongVerdictMemo.ABSENT, actual, "key " + Arrays.toString(row));
				} else {
					assertEquals(expected ? 1 : 0, actual, "key " + Arrays.toString(row));
				}
			}
		}
	}
}
